    final DataSourceCompactionConfig originalDatasourceConfig = DataSourceCompactionConfig
        .builder()
        .forDataSource(DS.WIKI)
        .withInputSegmentSizeBytes(500L)
        .withSkipOffsetFromLatest(Period.hours(1))
