    Assert.assertEquals(
        ImmutableMap.of(
            "listDim", ImmutableList.of("listDim1v1", "listDim1v2"),
            "dim3", 1,
            "dim2", "d2v1",
            "metric2", 2
        ),
        rows.get(0).getRaw("nestedData")
