            .withLoadTimeoutDelay(new Duration(1))
            .withCoordinatorKillMaxSegments(10)
            .withLoadQueuePeonRepeatDelay(new Duration("PT1s"))
            .withCoordinatorKillIgnoreDurationToRetain(false)
            .build()
    );

