                loadRequestRemoveSignal.countDown();
                break;
              default:
                // pass
            }
          }
        }
    );
    loadQueueCache.start();

    loadQueuePeon.loadSegment(
        segment,
        success -> {
          segmentLoadedSignal.countDown();
          delayedSegmentLoadedSignal.countDown();
