    loadQueueCache.getListenable().addListener(
        new PathChildrenCacheListener()
        {
          @Override
          public void childEvent(CuratorFramework client, PathChildrenCacheEvent event)
          {
            switch (event.getType()) {
              case CHILD_ADDED:
                loadRequestSignal.countDown();
                break;
