    Assert.assertEquals("bbb", jsonMap.get("nested-foo.bar2"));
    Assert.assertEquals("asdf", jsonMap.get("heybarx0"));
    Assert.assertEquals(ImmutableList.of(7L, 8L, 9L), jsonMap.get("met-array"));
