    Assert.assertEquals(
        convertSegmentTaskOriginal.getIndexSpec().getBitmapSerdeFactory().getClass().getCanonicalName(),
        convertSegmentTask.getIndexSpec()
                          .getBitmapSerdeFactory()
                          .getClass()
                          .getCanonicalName()
    );
